{
 "summary": "For every ν > 0, the two theorems assert Fefferman's breakdown alternatives. (C): there are smooth, divergence-free, rapidly decaying u₀ and f on ℝ³ such that no smooth (v,p) on ℝ³×[0,∞) solves Navier–Stokes with v(·,t) ∈ L² and uniformly bounded energy. (D): the same on the torus, with no smooth spatially 1-periodic solution. This matches the 'Consequently…' part of Theorem 1.1 and the final sentence of Corollary 10.6. The main caveat is in (D): the pressure must also be 1-periodic. That is an extra requirement inside the ¬∃ and makes the statement weaker, though it follows the Clay errata and the paper's periodic pressure P_per. The blow-up construction itself (compact support, L∞ blow-up as t↑1) is not formalized.",
 "glossary": [
  {"decl": "divergence", "line": 81, "plain": "∇·v(x) = trace of the Jacobian Dv(x); equals 0 where v is not differentiable", "standard_concept": "divergence of a vector field", "matches_standard": "yes", "note": "Junk value only at non-differentiable points; every use is on smooth fields."},
  {"decl": "IsOnePeriodic", "line": 121, "plain": "f(x+e_i) = f(x) for all x and every coordinate i", "standard_concept": "ℤⁿ-periodicity (function on 𝕋ⁿ)", "matches_standard": "yes", "note": ""},
  {"decl": "InitialVelocityCondition", "line": 134, "plain": "u₀ is C^∞ and ∇·u₀ = 0 everywhere", "standard_concept": "Fefferman's smooth divergence-free initial datum", "matches_standard": "yes", "note": ""},
  {"decl": "InitialVelocityConditionDecay", "line": 150, "plain": "In addition, for all m and all real K there is C with ‖D^m u₀(x)‖ ≤ C(1+|x|)^{-K}", "standard_concept": "Fefferman condition (4)", "matches_standard": "yes", "note": "Allowing K < 0 is a vacuous strengthening; the base is ≥ 1, so there is no junk division."},
  {"decl": "InitialVelocityConditionPeriodic", "line": 164, "plain": "Smooth, divergence-free and 1-periodic u₀", "standard_concept": "Fefferman condition (8)", "matches_standard": "yes", "note": ""},
  {"decl": "ForceCondition", "line": 175, "plain": "f is C^∞ on ℝⁿ×[0,∞)", "standard_concept": "smooth force", "matches_standard": "yes", "note": ""},
  {"decl": "ForceConditionDecay", "line": 185, "plain": "Every space-time derivative of f is bounded by C(1+|x|+t)^{-K} for t ≥ 0", "standard_concept": "Fefferman condition (5)", "matches_standard": "yes", "note": ""},
  {"decl": "ForceConditionPeriodic", "line": 200, "plain": "f(·,t) is 1-periodic for t ≥ 0, and every derivative is bounded by C(1+t)^{-K}", "standard_concept": "Fefferman conditions (8),(9)", "matches_standard": "yes", "note": ""},
  {"decl": "NavierStokesExistenceAndSmoothness", "line": 217, "plain": "(v,p) satisfy, for t ≥ 0: ∂_t v + (v·∇)v = νΔv − ∇p + f (one-sided time derivative); ∇·v = 0; v(·,0) = u₀; v and p are C^∞ on ℝⁿ×[0,∞)", "standard_concept": "Fefferman (1),(2),(3),(6)/(11)", "matches_standard": "yes", "note": ""},
  {"decl": "NavierStokesExistenceAndSmoothnessRn", "line": 245, "plain": "In addition, v(·,t) ∈ L² for each t ≥ 0 and sup_t ∫|v|² < E for some E", "standard_concept": "Fefferman condition (7)", "matches_standard": "yes", "note": "The MemLp hypothesis makes the Bochner integral genuine, not a junk 0."},
  {"decl": "NavierStokesExistenceAndSmoothnessPeriodic", "line": 262, "plain": "In addition, v(·,t) and p(·,t) are 1-periodic for t ≥ 0", "standard_concept": "Fefferman condition (10) plus the errata on pressure periodicity", "matches_standard": "partly", "note": "Pressure periodicity is not in Fefferman's original (10). It is the errata and standard fix, and matches the paper's P_per."}
 ],
 "lean_claims": [
  {"theorem": "navier_stokes_breakdown_R3", "line": 273, "plain": "For all ν > 0 there exist u₀, f: ℝ³ → ℝ³ (f time-dependent) such that u₀ is smooth, divergence-free and Schwartz-decaying, f is smooth on ℝ³×[0,∞) with all derivatives O((1+|x|+t)^{-K}), and there are no v, p that are smooth on ℝ³×[0,∞) and satisfy NS, ∇·v = 0, v(·,0) = u₀, v(·,t) ∈ L² for every t ≥ 0, and sup_{t≥0} ‖v(t)‖²_{L²} < ∞."},
  {"theorem": "navier_stokes_breakdown_periodic", "line": 280, "plain": "For all ν > 0 there exist smooth, divergence-free, 1-periodic u₀ and smooth, spatially 1-periodic f with all derivatives O((1+t)^{-K}), such that there are no smooth v, p on ℝ³×[0,∞) satisfying NS, ∇·v = 0, v(·,0) = u₀, with both v(·,t) and p(·,t) 1-periodic for every t ≥ 0."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "For every ν > 0 there exist f ∈ C_c^∞(ℝ³×(0,∞)), a compact set K, and smooth u, p on ℝ³×[0,1) solving NS with u(·,0) = 0, supported in K, with bounded L² norm and limsup_{t↑1} ‖u‖_∞ = ∞. Consequently there is no smooth solution on ℝ³×[0,∞) with the same data and uniformly bounded kinetic energy, i.e. alternative (C)."},
  {"ref": "Corollary 10.6", "plain": "For every ν > 0 there is a smooth force on 𝕋³×[0,∞), compactly supported in time, such that the periodic solution (U, P_per) with zero data blows up in L∞ as t↑1. There is no global smooth periodic solution for the same data, i.e. alternative (D)."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1 (consequence / alternative C)", "lean_theorem": "navier_stokes_breakdown_R3", "relation": "equivalent", "why": "Lean asserts Fefferman's (C); the paper's data (u₀ = 0, compactly supported f) are admissible witnesses."},
  {"paper_ref": "Theorem 1.1 (blow-up construction, compact support, L∞ blow-up)", "lean_theorem": null, "relation": "not_formalized", "why": "Only the non-existence consequence is stated."},
  {"paper_ref": "Corollary 10.6 (alternative D)", "lean_theorem": "navier_stokes_breakdown_periodic", "relation": "equivalent", "why": "Matches (D) with periodic pressure, consistent with the paper's P_per and the Clay errata. It is weaker than a literal reading of Fefferman's original (10)."},
  {"paper_ref": "Corollary 10.6 (blow-up of U on [0,1))", "lean_theorem": null, "relation": "not_formalized", "why": "Only non-existence is stated."}
 ],
 "flags": [
  {"id": "F1", "category": "assumption", "severity": "low", "decl": "NavierStokesExistenceAndSmoothnessPeriodic", "line": 269, "paper_ref": "Corollary 10.6", "explanation": "The solution must also have 1-periodic pressure. This is an extra requirement inside ¬∃, so the breakdown claim is weaker than Fefferman's original (D), which constrains only u. It follows the Clay errata and the paper's periodic pressure P_per. Without it, solutions with non-periodic pressure (e.g. a spatially constant velocity g(t) with p = −g'(t)·x) could exist.", "polarity": "lean weaker", "probe_idea": "State a variant without isOnePeriodic_pressure and compare. The constant-velocity/linear-pressure example shows the field is necessary for a meaningful (D)."},
  {"id": "F2", "category": "coverage", "severity": "low", "decl": "navier_stokes_breakdown_R3", "line": 273, "paper_ref": "Theorem 1.1", "explanation": "The paper's main content (an explicit smooth solution on [0,1) with compact support, bounded energy, and L∞ blow-up) is not formalized. Only the non-existence consequence is.", "polarity": "lean weaker", "probe_idea": null},
  {"id": "F3", "category": "other", "severity": "low", "decl": "NavierStokesExistenceAndSmoothness", "line": 223, "paper_ref": "Theorem 1.1", "explanation": "The time derivative is derivWithin on Ici 0 (one-sided at t = 0), and smoothness is ContDiffOn on univ ×ˢ Ici 0. This is a faithful encoding of C^∞(ℝ³×[0,∞)). Because v and p are required smooth, the fderiv, Δ and gradient terms are never junk.", "polarity": "n/a", "probe_idea": null}
 ],
 "lint_verdicts": [
  {"line": 81, "rule": "junk-deriv", "verdict": "harmless", "why": "Divergence is only applied to fields required to be C^∞, so fderiv is genuine."},
  {"line": 155, "rule": "junk-deriv", "verdict": "harmless", "why": "u₀ is required ContDiff ∞, so iteratedFDeriv is the true derivative."},
  {"line": 223, "rule": "junk-deriv", "verdict": "harmless", "why": "velocity_smooth on univ ×ˢ Ici 0 makes the spatial and one-sided time derivatives genuine for t ≥ 0."},
  {"line": 253, "rule": "junk-integral", "verdict": "harmless", "why": "The integrable field (MemLp ‖v·t‖ 2) guarantees ‖v‖² is integrable, so the integral is the true energy."},
  {"line": 155, "rule": "junk-div", "verdict": "harmless", "why": "The base 1+‖x‖ ≥ 1, so the rpow is positive and there is no division by zero."},
  {"line": 191, "rule": "junk-div", "verdict": "harmless", "why": "1+‖x‖+t ≥ 1 for t ≥ 0."},
  {"line": 205, "rule": "junk-div", "verdict": "harmless", "why": "1+t ≥ 1 for t ≥ 0."},
  {"line": 224, "rule": "nat-sub", "verdict": "harmless", "why": "This is subtraction of vectors in EuclideanSpace ℝ (Fin 3), not ℕ."}
 ]
